    }

    fn foreign_write(self) -> Result<PermissionProt> {
        match self {
            PermissionProt::Cell => ret(PermissionProt::Cell),
            PermissionProt::Frozen { had_local_read: true } | PermissionProt::Reserved { had_local_read: true, .. } =>
