/// This module controls how each permission individually reacts to an access.
/// Although these functions take `protected` as an argument, this is NOT because
/// we check protector violations here, but because some permissions behave differently
/// when protected.
mod transition {
    use super::*;
    /// A child node was read-accessed: UB on Disabled, noop on the rest.
    fn child_read(state: PermissionPriv, _protected: bool) -> Option<PermissionPriv> {
        Some(match state {
            Disabled => return None,
            // The inner data `ty_is_freeze` of `Reserved` is always irrelevant for Read
            // accesses, since the data is not being mutated. Hence the `{ .. }`.
            readable @ (Cell | ReservedFrz { .. } | ReservedIM | Unique | Frozen) => readable,
        })
    }

    /// A non-child node was read-accessed: keep `Reserved` but mark it as `conflicted` if it
    /// is protected; invalidate `Unique`.
    fn foreign_read(state: PermissionPriv, protected: bool) -> Option<PermissionPriv> {
        Some(match state {
            // Cell ignores foreign reads.
            Cell => Cell,
            // Non-writeable states just ignore foreign reads.
            non_writeable @ (Frozen | Disabled) => non_writeable,
            // Writeable states are more tricky, and depend on whether things are protected.
            // The inner data `ty_is_freeze` of `Reserved` is always irrelevant for Read
            // accesses, since the data is not being mutated. Hence the `{ .. }`

            // Someone else read. To make sure we won't write before function exit,
            // we set the "conflicted" flag, which will disallow writes while we are protected.
            ReservedFrz { .. } if protected => ReservedFrz { conflicted: true },
            // Before activation and without protectors, foreign reads are fine.
            // That's the entire point of 2-phase borrows.
            res @ (ReservedFrz { .. } | ReservedIM) => {
                // Even though we haven't checked `ReservedIM if protected` separately,
                // it is a state that cannot occur because under a protector we only
                // create `ReservedFrz` never `ReservedIM`.
                assert!(!protected);
                res
            }
            Unique =>
                if protected {
                    // We wrote, someone else reads -- that's bad.
                    // (Since Unique is always initialized, this move-to-protected will mean insta-UB.)
                    Disabled
                } else {
                    // We don't want to disable here to allow read-read reordering: it is crucial
                    // that the foreign read does not invalidate future reads through this tag.
                    Frozen
                },
        })
    }

    /// A child node was write-accessed: `Reserved` must become `Unique` to obtain
    /// write permissions, `Frozen` and `Disabled` cannot obtain such permissions and produce UB.
    fn child_write(state: PermissionPriv, protected: bool) -> Option<PermissionPriv> {
        Some(match state {
            // Cell ignores child writes.
            Cell => Cell,
            // If the `conflicted` flag is set, then there was a foreign read during
            // the function call that is still ongoing (still `protected`),
            // this is UB (`noalias` violation).
            ReservedFrz { conflicted: true } if protected => return None,
            // A write always activates the 2-phase borrow, even with interior
            // mutability
            ReservedFrz { .. } | ReservedIM | Unique => Unique,
            Frozen | Disabled => return None,
        })
    }

    /// A non-child node was write-accessed: this makes everything `Disabled` except for
    /// non-protected interior mutable `Reserved` which stay the same.
    fn foreign_write(state: PermissionPriv, protected: bool) -> Option<PermissionPriv> {
        // There is no explicit dependency on `protected`, but recall that interior mutable
        // types receive a `ReservedFrz` instead of `ReservedIM` when retagged under a protector,
        // so the result of this function does indirectly depend on (past) protector status.
        Some(match state {
            // Cell ignores foreign writes.
            Cell => Cell,
            res @ ReservedIM => {
                // We can never create a `ReservedIM` under a protector, only `ReservedFrz`.
                assert!(!protected);
                res
            }
            _ => Disabled,
        })
    }

    /// Dispatch handler depending on the kind of access and its position.
    pub(super) fn perform_access(
        kind: AccessKind,
        rel_pos: AccessRelatedness,
        child: PermissionPriv,
        protected: bool,
    ) -> Option<PermissionPriv> {
        match (kind, rel_pos.is_foreign()) {
            (AccessKind::Write, true) => foreign_write(child, protected),
            (AccessKind::Read, true) => foreign_read(child, protected),
            (AccessKind::Write, false) => child_write(child, protected),
            (AccessKind::Read, false) => child_read(child, protected),
        }
    }
}

/// - emitting protector UB if the location is accessed,
/// - updating the accessed status (child accesses produce accessed locations).
fn perform_access(
    &mut self,
    access_kind: AccessKind,
    rel_pos: AccessRelatedness,
    protected: bool,
) -> Result<PermTransition, TransitionError> {
    let old_perm = self.permission;
    let transition = Permission::perform_access(access_kind, rel_pos, old_perm, protected)
        .ok_or(TransitionError::ChildAccessForbidden(old_perm))?;
    self.accessed |= !rel_pos.is_foreign();
    self.permission = transition.applied(old_perm).unwrap();
    // Why do only accessed locations cause protector errors?
    // Consider two mutable references `x`, `y` into disjoint parts of
    // the same allocation. A priori, these may actually both be used to
    // access the entire allocation, as long as only reads occur. However,
    // a write to `y` needs to somehow record that `x` can no longer be used
    // on that location at all. For these non-accessed locations (i.e., locations
    // that haven't been accessed with `x` yet), we track the "future initial state":
    // it defaults to whatever the initial state of the tag is,
    // but the access to `y` moves that "future initial state" of `x` to `Disabled`.
    // However, usually a `Reserved -> Disabled` transition would be UB due to the protector!
    // So clearly protectors shouldn't fire for such "future initial state" transitions.
    //
    // See the test `two_mut_protected_same_alloc` in `tests/pass/tree_borrows/tree-borrows.rs`
    // for an example of safe code that would be UB if we forgot to check `self.accessed`.
    if protected && self.accessed && transition.produces_disabled() {
        return Err(TransitionError::ProtectedDisabled(old_perm));
    }
    debug_assert!(self.possible());
    Ok(transition)
}

/// Like `perform_access`, but ignores the concrete error cause and also uses state-passing
/// rather than a mutable reference. As such, it returns `Some(x)` if the transition succeeded,

    /// This is the special access that is applied on protector release:
    /// - the access will be applied only to accessed locations of the allocation,
    /// - it will not be visible to children,
    /// - it will be recorded as a `FnExit` diagnostic access
    /// - and it will be a read except if the location is `Unique`, i.e. has been written to,
    ///   in which case it will be a write.
    /// - otherwise identical to `Tree::perform_access`
    pub fn perform_protector_end_access(
        &mut self,
        tag: BorTag,
        global: &GlobalState,
        alloc_id: AllocId, // diagnostics
        span: Span,        // diagnostics
    ) -> InterpResult<'tcx> {
        #[cfg(feature = "expensive-consistency-checks")]
        if self.roots.len() > 1 {
            self.verify_wildcard_consistency(global);
        }

        let source_idx = self.tag_mapping.get(&tag).unwrap();

        let min_exposed_child = if self.roots.len() > 1 {
            LocationTree::get_min_exposed_child(source_idx, &self.nodes)
        } else {
            // There's no point in computing this when there is just one tree.
            None
        };

        // This is a special access through the entire allocation.
        // It actually only affects `accessed` locations, so we need
        // to filter on those before initiating the traversal.
        //
        // In addition this implicit access should not be visible to children,
        // thus the use of `traverse_nonchildren`.
        // See the test case `returned_mut_is_usable` from
        // `tests/pass/tree_borrows/tree-borrows.rs` for an example of
        // why this is important.
        for (loc_range, loc) in self.locations.iter_mut_all() {
            // Only visit accessed permissions
            if let Some(p) = loc.perms.get(source_idx)
                && let Some(access_kind) = p.permission.associated_access()
                && p.accessed
            {
                let diagnostics = DiagnosticInfo {
                    access_cause: AccessCause::FnExit(access_kind),
                    access_range: None,
                    alloc_id,
                    span,
                    transition_range: loc_range,
                };
                loc.perform_access(
                    self.roots.iter().copied(),
                    &mut self.nodes,
                    Some(source_idx),
                    access_kind,
                    global,
                    ChildrenVisitMode::SkipChildrenOfAccessed,
                    &diagnostics,
                    min_exposed_child,
                )?;
            }
        }
        interp_ok(())
    }
}

/// Associates with each location its state and wildcard access tracking.
pub(super) locations: DedupRangeMap<LocationTree>,
/// Contains both the root of the main tree as well as the roots of the wildcard subtrees.
///
/// If we reborrow a reference which has wildcard provenance, then we do not know where in
/// the tree to attach them. Instead we create a new additional tree for this allocation
/// with this new reference as a root. We call this additional tree a wildcard subtree.
///
/// The actual structure should be a single tree but with wildcard provenance we approximate
/// this with this ordered set of trees. Each wildcard subtree is the direct child of *some* exposed

let ty_is_freeze = pointee.is_freeze(*cx.tcx, cx.typing_env());
let is_protected = mode == RetagMode::FnEntry;

// Check if the implicit writes feature is globally enabled, using the
// `-Zmiri-tree-borrows-implicit-writes` flag, and not locally disabled using the
// `#[rustc_no_writable]` attribute. For performance reasons, only performs the lookup if
// is_protected is true as implicit writes are only performed for protected references.
let implicit_writes_enabled = is_protected && {
    let implicit_writes = cx.get_tree_borrows_params().implicit_writes;
    let def_id = cx.frame().instance().def_id();
    implicit_writes && !find_attr!(cx.tcx, def_id, RustcNoWritable)

let protected = new_perm.protector.is_some();
let precise_interior_mut = this.get_tree_borrows_params().precise_interior_mut;

// Compute initial "inside" permissions.
let loc_state = |frozen: bool| -> LocationState {
    let perm = if frozen { new_perm.freeze_perm } else { new_perm.nonfreeze_perm };
    let sifa = perm.strongest_idempotent_foreign_access(protected);

    if perm.associated_access().is_some() {
        LocationState::new_accessed(perm, sifa)
    } else {
        LocationState::new_non_accessed(perm, sifa)
    }
};
let inside_perms = if !precise_interior_mut {
    // For `!Freeze` types, just pretend the entire thing is an `UnsafeCell`.
    let ty_is_freeze = place.layout.ty.is_freeze(*this.tcx, this.typing_env());
    DedupRangeMap::new(ptr_size, loc_state(ty_is_freeze))
} else {
    // The initial state will be overwritten by the visitor below.
    let mut perms_map = DedupRangeMap::new(
        ptr_size,
        LocationState::new_accessed(
            Permission::new_disabled(),
            IdempotentForeignAccess::None,
        ),
    );
    this.visit_freeze_sensitive(place, ptr_size, |range, frozen| {
        let state = loc_state(frozen);
        for (_loc_range, loc) in perms_map.iter_mut(range.start, range.size) {
            *loc = state;
        }
        interp_ok(())
    })?;
    perms_map
};

let alloc_extra = this.get_alloc_extra(alloc_id)?;
let mut tree_borrows = alloc_extra.borrow_tracker_tb().borrow_mut();

for (perm_range, loc_state) in inside_perms.iter_all() {
    if let Some(access) = loc_state.permission().associated_access() {
        // Some reborrows incur a read/write access to the parent.
        // As a write also implies a read, a single write is performed instead of a read and a write.

        // writing to an immutable allocation (static variables) is UB, check this here
        if access == AccessKind::Write
            && this.get_alloc_mutability(alloc_id).unwrap().is_not()
        {
            throw_ub!(WriteToReadOnly(alloc_id))
        }

        // Adjust range to be relative to allocation start (rather than to `place`).
        let range_in_alloc = AllocRange {
            start: Size::from_bytes(perm_range.start) + base_offset,
            size: Size::from_bytes(perm_range.end - perm_range.start),
        };

        tree_borrows.perform_access(
            parent_prov,
            range_in_alloc,
            access,
            diagnostics::AccessCause::Reborrow(access),
            this.machine.borrow_tracker.as_ref().unwrap(),
            alloc_id,
            this.machine.current_user_relevant_span(),
        )?;

        // Also inform the data race model (but only if any bytes are actually affected).
        if range_in_alloc.size.bytes() > 0 {
            if let Some(data_race) = alloc_extra.data_race.as_vclocks_ref() {
                match access {
                    AccessKind::Read =>
                        data_race.read_non_atomic(
                            alloc_id,
                            range_in_alloc,
                            NaReadType::Retag,
                            Some(place.layout.ty),
                            &this.machine,
                        )?,
                    AccessKind::Write =>
                        data_race.write_non_atomic(
                            alloc_id,
                            range_in_alloc,
                            NaWriteType::Retag,
                            Some(place.layout.ty),
                            &this.machine,
                        )?,
                };
            }
        }
    }
}

